import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import time

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf', 'txt', 'html'}

os.makedirs(UPLOAD_DIR, exist_ok=True)

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def generate_job_id(filename):
    return hashlib.md5(f"{filename}{time.time()}".encode()).hexdigest()

@app.route('/api/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to PDF using LibreOffice"""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not allowed'}), 400

    # Get optional output format parameter
    output_format = request.form.get('format', 'pdf')

    # Save uploaded file
    filename = secure_filename(file.filename)
    job_id = generate_job_id(filename)
    job_dir = os.path.join(UPLOAD_DIR, job_id)
    os.makedirs(job_dir, exist_ok=True)

    input_path = os.path.join(job_dir, filename)
    file.save(input_path)

    # Build conversion command
    # The output_format is user-controlled and injected into shell command
    cmd = f"libreoffice --headless --convert-to {output_format} --outdir {job_dir} {input_path}"

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=job_dir
        )

        if result.returncode != 0:
            return jsonify({
                'error': 'Conversion failed',
                'details': result.stderr.decode('utf-8', errors='replace')[:200]
            }), 500

        # Find the output file
        output_ext = output_format.split(':')[0] if ':' in output_format else output_format
        base_name = os.path.splitext(filename)[0]
        output_path = os.path.join(job_dir, f"{base_name}.{output_ext}")

        if os.path.exists(output_path):
            return send_file(output_path, as_attachment=True)
        else:
            # Try to find any new file in the directory
            files = os.listdir(job_dir)
            new_files = [f for f in files if f != filename]
            if new_files:
                return send_file(os.path.join(job_dir, new_files[0]), as_attachment=True)
            return jsonify({'error': 'Output file not found'}), 500

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/status', methods=['GET'])
def status():
    """Health check endpoint"""
    return jsonify({'status': 'healthy', 'version': '2.1.0'})

@app.route('/api/formats', methods=['GET'])
def list_formats():
    """List supported input/output formats"""
    return jsonify({
        'input': list(ALLOWED_EXTENSIONS),
        'output': ['pdf', 'docx', 'odt', 'html', 'txt', 'epub']
    })

# Cleanup old jobs periodically (called by cron)
@app.route('/internal/cleanup', methods=['POST'])
def cleanup():
    auth = request.headers.get('X-Internal-Auth')
    if auth != os.environ.get('INTERNAL_SECRET', 'changeme'):
        return jsonify({'error': 'unauthorized'}), 403

    cutoff = time.time() - 3600
    cleaned = 0
    for job_id in os.listdir(UPLOAD_DIR):
        job_path = os.path.join(UPLOAD_DIR, job_id)
        if os.path.isdir(job_path) and os.path.getmtime(job_path) < cutoff:
            subprocess.run(['rm', '-rf', job_path])
            cleaned += 1
    return jsonify({'cleaned': cleaned})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
